  ?s a ?cls .
  FILTER (STRSTARTS(STR(?zone), "http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_")) .
  FILTER (CONTAINS(STR(?cls), "Temperature_Sensor")) .
  OPTIONAL {?s brick:hasExternalReference ?ref . ?ref <https://brickschema.org/schema/Brick/ref#hasTimeseriesId> ?ts .}
}

